// Generated by philote from page /horses/[id]. Do not edit.
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { readHorseView } from "@/lib/reads";

import HorseView from "@/components/common/horse-view";

export const metadata: Metadata = { title: "Horse" };

export default function Page({ params }: PageProps<"/horses/[id]">) {
    return (
        <main className="flex flex-1 flex-col">
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections params={params} />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell, so a missing record
// renders not-found.tsx with noindex, but the response status stays 200.
async function Sections({ params }: Pick<PageProps<"/horses/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await api.horses.get(id);
    if (!result.ok) {
        notFound();
    }
    const loaded = result.value;
    const props1 = await readHorseView(loaded);
    return (
        <>
            <HorseView {...props1} />
        </>
    );
}
